7	)
8	
9	// Liveness is what Probe says of the process a row was listed with.
10	type Liveness int
11	
12	const (
13		// ProcessRunning is the zero value on purpose: a probe that could not read
14		// anything counts the process as still there, never as stopped.
15		ProcessRunning Liveness = iota // the listed process still holds the PID
16		ProcessZombie                  // it exited and its parent has not reaped it yet
17		ProcessExited                  // no process holds the PID, or another one does
18	)
19	
20	// Stopped reports whether the listed process is gone for good: exited, or a
21	// zombie, which holds a PID but runs nothing.
22	func (l Liveness) Stopped() bool { return l != ProcessRunning }
23	
24	// String is for logs only.
25	func (l Liveness) String() string {
26		switch l {
27		case ProcessRunning:
28			return "running"
29		case ProcessZombie:
30			return "zombie"
31		case ProcessExited:
32			return "exited"
33		default:
34			return fmt.Sprintf("Liveness(%d)", int(l))
35		}
36	}
37	
38	// Probe says, without signalling anything, what became of the process a row was
39	// listed with (DEVDESK-711): still running, a zombie, or gone. One read gives
40	// both the state and the identity stamp, and the stamp is compared with listed,
41	// so a PID taken by another process reads as exited.
42	//
43	// A read that fails for another reason than "no such process" returns
44	// ProcessRunning with the error: an unreadable probe is never taken for a stop.
45	// Windows has no probe (errors.ErrUnsupported): it has no clean stop to watch.
46	func Probe(pid string, listed Identity) (Liveness, error) {
47		n, ok := parsePID(pid)
48		if !ok || n <= 0 {
49			return ProcessRunning, fmt.Errorf("not a process id: %q", pid)
50		}
51		if listed.kind != identityKnown {
52			return ProcessRunning, &UnverifiableError{PID: n}
53		}
54		if goos == "windows" {
55			return ProcessRunning, fmt.Errorf("probing process %d: %w", n, errors.ErrUnsupported)
56		}
57		st, err := procOS.probe(n)
58		return livenessOf(listed, st, err)
59	}
60	
61	// livenessOf is the decision of Probe, apart from the read.
62	func livenessOf(listed Identity, st procStatus, err error) (Liveness, error) {
63		if err != nil {
64			if errors.Is(err, os.ErrProcessDone) {
65				return ProcessExited, nil
66			}
67			return ProcessRunning, fmt.Errorf("probing the process: %w", err)
68		}
69		if st.start != listed.raw {
70			return ProcessExited, nil // the PID changed hands: the listed process is gone
71		}
72		if st.zombie {
73			return ProcessZombie, nil
74		}
75		return ProcessRunning, nil
76	}
