// handleKeyRunning cancels the run. The stage in flight is awaited rather than
// interrupted — it is a network read that will time out on its own — and its
// result is discarded by the generation counter.
func (m *Model) handleKeyRunning(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	if msg.String() != "esc" {
		return m, nil
	}
	m.runGen++
	m.state = StateResults
	m.verdict = netcheck.Summarize(m.results.All())
	m.rebuildChecksTable()
	return m, m.footer.Warn("Run cancelled — showing what completed")
}

func (m *Model) handleKeyInput(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "down":
		return m, m.moveFocus(1)
	case "up":
		return m, m.moveFocus(-1)
	case "enter":
		// enter runs the checks from anywhere in the form, so the user need
		// not walk to the button first; only the Trace Path button means
		// something else.
		if m.focusedField == fieldTraceButton {
			return m.traceFromForm()
		}
		return m.StartRun()
	case "esc":
		return m, nil
	}
	return m.updateActiveInput(msg)
}

// moveFocus moves the focus by delta fields and returns the Focus command of
// the field that takes it (nil on a button), which restarts the cursor blink.
func (m *Model) moveFocus(delta int) tea.Cmd {
	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Blur()
	case fieldPort:
		m.portInput.Blur()
	case fieldDNSServer:
		m.dnsServerInput.Blur()
	}

		m.width = msg.Width
		m.height = msg.Height

	case tea.KeyPressMsg:
		switch msg.String() {
		case "left", "right":
			// Toggle between Yes and No (Rule 135 — Tab exclusively for tabs)
			m.focused = !m.focused
			return m, nil

		case "enter":
			// Confirm the selection
			if m.focused {
				return m, func() tea.Msg {
					return ConfirmModalYesMsg{}
				}
			} else {
				return m, func() tea.Msg {
					return ConfirmModalNoMsg{}
				}
			}

		case "y", "Y":
			// Shortcut for Yes
			return m, func() tea.Msg {
				return ConfirmModalYesMsg{}
			}

		case "n", "N", "esc":
			// Shortcut for No
			return m, func() tea.Msg {
				return ConfirmModalNoMsg{}
			}
		}
	}

	return m, nil
}

